const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^\d+$/

function lineFailure(line, message) {
  return new CliFailure(2, `error: line ${line}: ${message}`)
}

function splitInputLines(input) {
  const lines = input.split('\n')
  if (input.endsWith('\n')) lines.pop()
  return lines
}

/**
 * Parses the build graph in `input` into a map of task costs and an
 * adjacency map from a task name to the set of names it depends on.
 * Throws a CliFailure for any malformed directive, unknown task or cycle.
 */
export function parseGraph(input) {
  const lines = splitInputLines(input)
  const tasks = new Map()
  const depLines = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) throw lineFailure(lineNumber, 'expected task <name> <cost>')
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) throw lineFailure(lineNumber, `invalid task name ${name}`)
      if (!COST_RE.test(costStr)) throw lineFailure(lineNumber, 'cost must be a non-negative integer')
      if (tasks.has(name)) throw lineFailure(lineNumber, `task ${name} is declared twice`)
      tasks.set(name, Number(costStr))
    } else if (directive === 'dep') {
      if (words.length < 3) throw lineFailure(lineNumber, 'expected dep <name> <dependency>...')
      const [, name, ...deps] = words
      for (const candidate of [name, ...deps]) {
        if (!NAME_RE.test(candidate)) throw lineFailure(lineNumber, `invalid task name ${candidate}`)
      }
      depLines.push({ name, deps })
    } else {
      throw lineFailure(lineNumber, `unknown directive ${directive}`)
    }
  }

  for (const { name, deps } of depLines) {
    for (const candidate of [name, ...deps]) {
      if (!tasks.has(candidate)) throw new CliFailure(2, `error: unknown task ${candidate}`)
    }
  }

  const adjacency = new Map()
  for (const name of tasks.keys()) adjacency.set(name, new Set())
  for (const { name, deps } of depLines) {
    const set = adjacency.get(name)
    for (const dep of deps) set.add(dep)
  }

  return { tasks, adjacency }
}
"}

