/**
 * Walks the graph depth-first from each task in ascending name order,
 * visiting each task's dependencies in ascending name order, and throws a
 * CliFailure describing the first cycle it re-enters.
 */
function checkForCycle(tasks, adjacency) {
  const names = [...tasks.keys()].sort()
  const UNVISITED = 0
  const VISITING = 1
  const DONE = 2
  const state = new Map(names.map((name) => [name, UNVISITED]))
  const stack = []

  function visit(name) {
    state.set(name, VISITING)
    stack.push(name)
    const deps = [...adjacency.get(name)].sort()
    for (const dep of deps) {
      if (state.get(dep) === VISITING) {
        const start = stack.indexOf(dep)
        const cycle = [...stack.slice(start), dep]
        throw new CliFailure(3, `error: cycle: ${cycle.join(' -> ')}`)
      }
      if (state.get(dep) === UNVISITED) visit(dep)
    }
    stack.pop()
    state.set(name, DONE)
  }

  for (const name of names) {
    if (state.get(name) === UNVISITED) visit(name)
  }
}

/**
 * Computes, for every task, its start time, finish time and wave depth as
 * defined by the specification: start is the greatest finish among its
 * dependencies (0 with none), finish is start plus cost, and depth is 0
 * with no dependencies or one more than the deepest dependency's depth.
 * Assumes the graph is acyclic.
 */
function computeTimings(tasks, adjacency) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  function compute(name) {
    if (finish.has(name)) return
    const deps = [...adjacency.get(name)]
    let taskStart = 0
    let taskDepth = 0
    for (const dep of deps) {
      compute(dep)
      taskStart = Math.max(taskStart, finish.get(dep))
      taskDepth = Math.max(taskDepth, depth.get(dep) + 1)
    }
    start.set(name, taskStart)
    finish.set(name, taskStart + tasks.get(name))
    depth.set(name, taskDepth)
  }

  for (const name of tasks.keys()) compute(name)
  return { start, finish, depth }
}

/**
 * Builds the full schedule for a parsed graph: per-task start, finish and
 * depth, the tasks grouped by wave, and the unlimited-worker makespan.
 * Throws a CliFailure if the graph contains a cycle.
 */
export function buildSchedule({ tasks, adjacency }) {
  checkForCycle(tasks, adjacency)
  const { start, finish, depth } = computeTimings(tasks, adjacency)

  const waves = new Map()
  for (const name of tasks.keys()) {
    const d = depth.get(name)
    if (!waves.has(d)) waves.set(d, [])
    waves.get(d).push(name)
  }
  for (const names of waves.values()) names.sort()

  let total = 0
  for (const name of tasks.keys()) total = Math.max(total, finish.get(name))

  return { start, finish, depth, waves, total }
}
