import { parseGraph } from './parser.js'
import { buildSchedule } from './graph.js'
import { packWorkers } from './pack.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^[1-9]\d*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliFailure(2, 'error: workers must be a positive integer')
    }
    return { mode: 'pack', workers: Number(argv[1]) }
  }
  throw new CliFailure(2, USAGE)
}

function renderWaves(schedule) {
  const lines = []
  const depths = [...schedule.waves.keys()].sort((a, b) => a - b)
  for (const depth of depths) {
    lines.push(`wave ${depth}: ${schedule.waves.get(depth).join(' ')}`)
  }
  lines.push(`total ${schedule.total}`)
  return lines.map((line) => line + '\n').join('')
}

function renderExplain(graph, schedule) {
  const lines = []
  for (const name of [...graph.tasks.keys()].sort()) {
    const s = schedule.start.get(name)
    const f = schedule.finish.get(name)
    const d = schedule.depth.get(name)
    lines.push(`${name} start=${s} finish=${f} depth=${d}`)
  }
  lines.push(`total ${schedule.total}`)
  return lines.map((line) => line + '\n').join('')
}

function renderPack(result) {
  const lines = []
  result.workers.forEach((worker, i) => {
    const tasks = worker.log.map((entry) => ` ${entry.name}@${entry.start}-${entry.finish}`).join('')
    lines.push(`worker ${i}:${tasks}`)
  })
  lines.push(`makespan ${result.makespan}`)
  return lines.map((line) => line + '\n').join('')
}

function main() {
  const args = parseArgs(process.argv.slice(2))
  const input = readFileSync(0, 'utf8')
  const graph = parseGraph(input)

  if (args.mode === 'waves') {
    process.stdout.write(renderWaves(buildSchedule(graph)))
  } else if (args.mode === 'explain') {
    const schedule = buildSchedule(graph)
    process.stdout.write(renderExplain(graph, schedule))
  } else {
    buildSchedule(graph) // validates acyclicity before simulating
    process.stdout.write(renderPack(packWorkers(graph, args.workers)))
  }
}

try {
  main()
} catch (err) {
  if (err instanceof CliFailure) {
    process.stderr.write(err.message + '\n')
    process.exit(err.code)
  }
  throw err
}
